// Task-local script: fetch contacts from the email API and save to contacts.txt
// Uses only Node.js built-ins (fs, https via global fetch) - no npm deps.

const fs = require("fs");
const path = require("path");

const BASE_URL = "https://agenskill-api.onrender.com";

function loadCredentials() {
  const credsPath = path.join(__dirname, "email_credentials.json");
  const raw = fs.readFileSync(credsPath, "utf8");
  const parsed = JSON.parse(raw);
  return {
    email: parsed.account.email,
    apiKey: parsed.account.api_key,
  };
}

function extractContacts(payload) {
  // Handle common response shapes defensively.
  if (Array.isArray(payload)) return payload;
  if (payload && Array.isArray(payload.contacts)) return payload.contacts;
  if (payload && Array.isArray(payload.data)) return payload.data;
  if (payload && Array.isArray(payload.results)) return payload.results;
  return [];
}

function formatContact(c) {
  if (typeof c === "string") return c;
  if (!c || typeof c !== "object") return String(c);
  const name = c.name || c.fullName || c.displayName || c.username || "";
  const email =
    c.email ||
    c.emailAddress ||
    (c.emails && c.emails[0]) ||
    (c.emailAddresses && c.emailAddresses[0]) ||
    "";
  const phone = c.phone || c.phoneNumber || c.phone_numbers || "";
  const parts = [];
  if (name) parts.push(`Name: ${name}`);
  if (email) parts.push(`Email: ${email}`);
  if (phone) parts.push(`Phone: ${phone}`);
  if (parts.length === 0) {
    return JSON.stringify(c);
  }
  return parts.join(" | ");
}

async function main() {
  const { email, apiKey } = loadCredentials();

  const res = await fetch(`${BASE_URL}/contacts`, {
    method: "GET",
    headers: {
      "X-API-Key": apiKey,
      "X-User-Email": email,
      Accept: "application/json",
    },
  });

  const rawText = await res.text();
  let payload;
  try {
    payload = JSON.parse(rawText);
  } catch (e) {
    console.error(JSON.stringify({ success: false, error: "Non-JSON response", status: res.status, body: rawText }));
    process.exit(1);
  }

  if (!res.ok) {
    console.error(JSON.stringify({ success: false, error: payload, status: res.status }));
    process.exit(1);
  }

  const contacts = extractContacts(payload);

  const lines = [];
  lines.push("=== Contact List ===");
  lines.push(`Total contacts: ${contacts.length}`);
  lines.push("");
  contacts.forEach((c, i) => {
    lines.push(`${i + 1}. ${formatContact(c)}`);
  });

  const outPath = path.join(__dirname, "contacts.txt");
  fs.writeFileSync(outPath, lines.join("\n") + "\n", "utf8");

  console.log(
    JSON.stringify({
      success: true,
      total: contacts.length,
      savedTo: outPath,
      contacts: contacts.map(formatContact),
    })
  );
}

main().catch((err) => {
  console.error(JSON.stringify({ success: false, error: err.message }));
  process.exit(1);
});

