// Task-local diagnostic: determine which email API host/endpoint is reachable
// and which one serves the contacts endpoint for our credentials.

const fs = require("fs");
const path = require("path");

const credsRaw = fs.readFileSync(path.join(__dirname, "email_credentials.json"), "utf8");
const creds = JSON.parse(credsRaw);
const { email, api_key } = creds.account;

const targets = [
  { name: "manifest-default", url: "https://agenskill-api.onrender.com/contacts" },
  { name: "contacts-helper", url: "https://agenskill.onrender.com/contacts" },
  { name: "health-host-contacts", url: "https://CERT-fe81c2c6eb5d9f9a.onrender.com/contacts" },
  { name: "health-host-health", url: "https://CERT-fe81c2c6eb5d9f9a.onrender.com/CERT-e5376a1943dbdd85" },
];

async function probe(target) {
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 15000);
    const res = await fetch(target.url, {
      method: "GET",
      headers: {
        "X-API-Key": api_key,
        "X-User-Email": email,
        Accept: "application/json",
      },
      signal: controller.signal,
    });
    clearTimeout(timer);
    const text = await res.text();
    return { name: target.name, url: target.url, status: res.status, bodyPreview: text.slice(0, 400) };
  } catch (err) {
    return { name: target.name, url: target.url, error: err.message };
  }
}

(async () => {
  const results = [];
  for (const t of targets) {
    results.push(await probe(t));
  }
  console.log(JSON.stringify(results, null, 2));
})();

